from html import escape

def content(d,fit=None):
 def f(x,n=1): return f'{x:,.{n}f}'.replace(',','\u202f').replace('.',',')
 v=d['cases'][0]; k=d['selected']; inp=d['input']; p=inp['cycle']; a=v['assumptions']; wp=(p['p_in_Pa']-2e5)/(inp['cycle']['rho_feed_kg_m3']*.55)
 formulas=[('Рабочий объём','V = N · πD²S / 4',f"7 × π × 0,040² × 0,045 / 4 = {f(v['geometry']['swept_L'],3)} л. Двойное действие не удваивает обычный рабочий объём."),('Объём двух рабочих сторон за оборот кривошипа','V₂ = N · π(2D² − d²)S / 4',f"7 × π × (2 × 0,040² − 0,0096²) × 0,045 / 4 = {f(v['geometry']['double_L'],3)} л. За оборот общего вала проходят два оборота каждого кривошипа."),('Расход пара из теплового баланса','ṁ = Q̇ / (h₁ − hпод − wнас)',f"50\u202f000 / ({f(p['h_in_J_kg'],0)} − {f(p['h_feed_J_kg'],0)} − {f(wp,0)}) = {f(v['mass_kg_h']/3600,5)} кг/с = {f(v['mass_kg_h'],1)} кг/ч."),('Обороты по расходу','nкр = 60ṁ / (ρ · V₂ · отсечка · наполнение); nвых = nкр / 2',f"60 × {f(v['mass_kg_h']/3600,5)} / ({f(inp['steam']['density_kg_m3'],4)} × {f(v['geometry']['double_L']/1000,7)} × 0,30 × 0,85) = {f(v['crank_rpm'],0)} об/мин; выход {f(v['output_rpm'],0)} об/мин."),('Мощность до вспомогательных нагрузок','Pвал = ṁ · (h₁ − h₂s) · ηis · ηмех',f"{f(v['mass_kg_h']/3600,5)} × {f(p['dh_is_J_kg'],0)} × 0,50 × 0,90 = {f(v['shaft_kW'],2)} кВт = {f(v['shaft_hp'],2)} л.с. КПД гипотетические, не паспорт двигателя."),('Момент общего вала','M = 1000P / (2πnвых/60)',f"{f(v['shaft_kW']*1000,0)} / (2π × {f(v['output_rpm'],1)} / 60) = {f(v['torque_output_Nm'],1)} Н·м."),('Полезная мощность','Pпол = Pвал − Pэл/ηген',f"{f(v['shaft_kW'],2)} − {f(v['electric_kW'],2)} / 0,85 = {f(v['net_kW'],2)} кВт при нагреве воздуха25 К. Это предварительный баланс, не мощность на колёсах."),('Нагрузка охлаждения','Q̇отв = Q̇пара + Pнас − Pиндик; V̇возд = Q̇отв/(ρвозд cₚ ΔT)',f"50 + {f(v['pump_kW'],3)} − {f(v['indicated_kW'],2)} = {f(v['reject_kW'],1)} кВт; {f(v['reject_kW']*1000,0)} / (1,18 × 1005 × 25) = {f(v['air_m3_s'],2)} м³/с."),('Скорость свежего пара','u = ṁ/(ρ · πDт²/4)',f"{f(v['mass_kg_h']/3600,5)} / ({f(inp['steam']['density_kg_m3'],4)} × π × 0,040² / 4) = {f(d['pipe_screen']['inlet_speed_m_s'],2)} м/с в основной трубеID40. В отдельнойID8 подаче к цилиндру средняя скорость {f(d['pipe_screen']['average_per_cylinder_inlet_m_s'],1)} м/с; за время открытого впуска оценка {f(d['pipe_screen']['estimated_open_branch_speed_m_s'],1)} м/с. Пульсации и потери клапанов ещё не рассчитаны.")]
 cards=''.join(f'<article class="thermal-formula"><h3>{escape(t)}</h3><p><code>{escape(eq)}</code></p><p>{escape(sub)}</p></article>' for t,eq,sub in formulas)
 rows=''.join(f'<tr><td>Ø{f(r["bore_mm"],0)} × {f(r["stroke_mm"],2)}</td><td>{f(r["calculation"]["geometry"]["swept_L"],3)} л</td><td>{" × ".join(f(x,0) for x in r["size_mm"])}</td><td>{f(r["gaps"]["BODY"],1)} мм</td><td>{"Пересекает: "+", ".join(sorted(set(x["id"] for x in r["conflicts"]))) if r["conflicts"] else "Без пересечений в этом проходе"}</td></tr>' for r in d['tables'])
 heat=''.join(f'<tr><td>{f(c["heat_kW"],0)}</td><td>{f(c["assumptions"]["air_rise_K"],0)}</td><td>{f(c["crank_rpm"],0)} / {f(c["output_rpm"],0)}</td><td>{f(c["shaft_kW"],2)}</td><td>{f(c["net_kW"],2)}</td><td>{f(c["fuel_L_h"],1)}</td><td>{f(c["reject_kW"],1)}</td></tr>' for c in d['cases'])
 engine=fit.get('enginePart',{}) if fit else {}; summary=fit.get('audit',{}).get('summary',{}) if fit else {}
 proof=f'<p>Финальный аудит: двигатель — {len(engine.get("body_intersections",[]))} пересечений с кузовом, {len(engine.get("stock_intersections",[]))} со статической подвеской. Зазор до сетки кузова {f(engine.get("clearance_mm",18),1)} мм; опорные площадки до пола — намеренный контакт.</p>'
 if summary: proof+=f'<p>У всей установки остаётся {len(summary.get("body_conflicts",[]))} объектов с пересечениями панелей и {len(summary.get("unplanned_mesh_intersections",[]))} отмеченных пересечений агрегатов. Полный список сохранён в JSON; эти проблемы не скрыты.</p>'
 sources=''.join(f'<li><a href="{escape(s["url"],quote=True)}">{escape(s["title"])}</a></li>' for s in d['sources'])
 limits=''.join(f'<li>{escape(s)}</li>' for s in d['limitations'])
 return f'''<section class="page-intro"><span class="eyebrow">ПОДБОР ПО ГЕОМЕТРИИ / 10.10.2026</span><h1>Семь цилиндров под наш кузов</h1><p>Выбран Ø40 мм × ход45 мм: рабочий объём <strong>{f(v['geometry']['swept_L'],3)} л</strong>. С коллекторами, изоляцией и угловой передачей — <strong>589 × 589 × 375 мм</strong> без стоек до пола. Двигатель установлен в основной сборке, а не только в отдельном просмотрщике.</p><div class="hero-actions"><a class="button" href="assembly.html?component=ENG">Открыть двигатель в основной 3D-сборке</a><a class="button secondary" href="assembly.html">Весь автомобиль</a><a class="button secondary" href="models/fitted-radial-engine.glb" download>Скачать двигатель GLB</a><a class="button secondary" href="drawings/11-fitted-radial.pdf">Размерная схема PDF</a></div></section><section><h2>Почему этот размер</h2><p>Механизм: семь отдельных кривошипов со шатунами и крейцкопфами передают вращение через семь шестерён28 зубьев на общую шестерню56 зубьев; угловая передача направляет выход к КПП. Это проектная кинематика, без подтверждённой прочности шестерён и валов. Сохранили семь горизонтальных цилиндров двойного действия, сдвиг фаз360/7° и отношение хода к диаметру1,125. Меняются механические размеры, но диаметры труб, изоляция и коллекторы остаются в масштабе1:1. Двигатель с семью Ø100 × 120 имел6,597 л и прежний габарит1492 × 1448 × 329 мм; в этом отсеке он не помещается.</p><p>В испытанной семье Ø40 проходит по предоставленной игровой сетке, соседним агрегатам и нынешнему дизельному каналу; уже Ø41 задевает дымовой тракт. Это выбор для данной компоновки, не математически максимальный двигатель для любого механизма или перестановки.</p><div class="table-scroll"><table><thead><tr><th>Диаметр × ход, мм</th><th>Рабочий объём</th><th>Габарит со всей обвязкой, мм</th><th>До кузова</th><th>Кузов, соседи, дизельный канал</th></tr></thead><tbody>{rows}</tbody></table></div>{proof}<p>Сетка кузова yatloo не является обмеренным CAD. Реальную посадку надо подтвердить измерением отсека, оси КПП, движения подвески и горячих зазоров. Архивный резерв600 × 500 × 500 мм больше не используется как единственное ограничение.</p></section><section><h2>Формула → наши данные → результат</h2><p>Исходный режим: 10 бар абсолютного, 250 °C на входе, противодавление1,2 бар, вода подачи60 °C. Энтальпии и плотность взяты из сохранённых таблиц IAPWS/CoolProp; между узлами использована прежняя интерполяция проекта.</p>{cards}</section><section><h2>Один двигатель, разные тепловые режимы</h2><p>Больший объём снижает требуемые обороты при одинаковом расходе пара; мощность при этом задаёт энтальпийный поток. Полезная мощность учитывает предварительную нагрузку охлаждения, насосов и горелки. Вариант с нагревом воздуха45 К — отдельная гипотеза, не подтверждённый способ исправить охлаждение.</p><div class="table-scroll"><table><thead><tr><th>Тепло в пар, кВт</th><th>Нагрев воздуха, К</th><th>Кривошипы / выход, об/мин</th><th>На валу, кВт</th><th>Полезная, кВт</th><th>Дизель, л/ч</th><th>Отвод тепла, кВт</th></tr></thead><tbody>{heat}</tbody></table></div><p>102 кВт тепла — 120 кВт топлива × КПД нагрева0,85. Нужные2699 об/мин выше принятого исследовательского предела2600. Отрицательный результат полезной мощности означает недостаток мощности на вспомогательные узлы в этой гипотезе, а не «отрицательную мощность» двигателя. Для40 л.с. на валу потребовалось бы около{f(d['target_40_hp']['heat_kW'],0)} кВт тепла в паре — текущий источник этого не обеспечивает.</p></section><details class="systems-panel"><summary>Что ещё не подтверждено</summary><ul>{limits}</ul></details><section><h2>Расчёт и проверка</h2><div class="hero-actions"><a href="fitted-engine-study.json">Все исходные данные и результаты JSON</a><a href="fitted-engine-fit.json">Финальный аудит всей сборки JSON</a><a href="models/fitted-radial-in-car.glb" download>Полная сборка GLB</a></div><ul>{sources}</ul><p>Архив: <a href="compact-radial.html">Ø32 × 36</a> · <a href="engine-sizing.html">старый подбор под резерв</a>. Новая симуляция использует7 цилиндров Ø40 × 45, шток9,6 и передачу2:1; прежний расчёт сил двух Ø100 не применяется к новой звезде.</p></section>'''
